/**
* GA4 conversion events.
*
* Fires the three business conversions so they can be marked as key events
* (what used to be called "goals") in the GA4 UI:
*
*   generate_lead    — demo request submitted
*   contact_click    — phone / WhatsApp / email tapped on the contact page
*   job_application  — careers application submitted
*
* Note on "contact form": the contact page has no form — it lists phone,
* WhatsApp and email links — so the meaningful conversion there is the click
* on one of those, which is what contact_click records.
*
* Every call is guarded: if gtag is absent (analytics ID not configured, or
* the visitor blocks it) these are silent no-ops and nothing on the page
* breaks.
*/
(function () {
'use strict';
function track(eventName, params) {
try {
if (typeof window.gtag === 'function') {
window.gtag('event', eventName, params || {});
}
} catch (e) { /* analytics must never break the page */ }
}
// Exposed so other scripts (e.g. the demo form) can fire conversions.
window.epTrackConversion = track;
document.addEventListener('DOMContentLoaded', function () {
// --- contact_click: phone / WhatsApp / email ---
document.querySelectorAll('a[href^="tel:"], a[href^="mailto:"], a[href*="wa.me"]').forEach(function (a) {
a.addEventListener('click', function () {
var href = a.getAttribute('href') || '';
var method = href.indexOf('wa.me') !== -1 ? 'whatsapp'
: href.indexOf('mailto:') === 0 ? 'email'
: 'phone';
track('contact_click', {
method: method,
page_location: window.location.pathname
});
});
});
// --- job_application: fired once when the thank-you panel is rendered ---
if (document.querySelector('[data-conversion="job_application"]')) {
track('job_application', { page_location: window.location.pathname });
}
});
})();